panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:64px 60px 0;background:radial-gradient(circle at 10% 20%,rgba(214,62,118,.12),transparent 45%),radial-gradient(circle at 92% 80%,rgba(245,197,24,.16),transparent 48%),var(--cream)}
.k{font-size:32px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:66px;font-weight:900;line-height:1.25;text-align:center;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.one{position:absolute;left:60px;right:60px;bottom:64px;text-align:center;font-size:34px;font-weight:700;background:#46293A;color:#fff;border-radius:18px;padding:22px 16px}.one b{color:#F5C518;font-weight:900}
.lgtop{text-align:center}.lgtop img{width:300px;height:auto;background:#fff;border-radius:14px;padding:14px 20px;box-shadow:0 10px 24px -18px rgba(30,18,25,.4)}
.k{margin-top:20px}
.st{margin-top:32px;display:flex;flex-direction:column;gap:18px}
.r{display:flex;align-items:center;gap:24px;background:#fff;border-radius:22px;padding:20px 28px;box-shadow:0 14px 30px -22px rgba(30,18,25,.4)}
.n{flex:0 0 70px;height:70px;border-radius:50%;background:#D63E76;color:#fff;font-size:40px;font-weight:900;display:flex;align-items:center;justify-content:center}
.tx{font-size:28px;font-weight:700;color:var(--ink-2)}.tx b{display:block;font-size:38px;font-weight:900;color:var(--ink)}
